-- 016: the SEO team's "recycle_technologies_content_action_plan_finale" sheet
-- (14 Oct 2026), the parts that live in the database. The pages built in code
-- carry their new titles and descriptions in src/data/page-seo.ts
-- (CONTENT_PLAN_14_OCT).
--
--   1. Blog posts: the new SEO title (meta_title), H1 (title) and meta
--      description, from tabs 03 Meta Missing, 05 Title Over 60, 06 Meta Over
--      155, 07 Meta Duplicate, 10 Title Same as H1 and 11 H1 Over 70, word for
--      word. NULL means "leave that field as it is". Tab 10's four typo rows
--      ("Upmost", "Don`t", "Monitor Recycling ?How", "responsibly?") also get
--      the corrected H1 the sheet spells out.
--      Tab 11's H1 column sits one row above its URL in the sheet; the H1s here
--      are matched to the right post.
--   2. Admin -> Pages edits of the title or description of the code pages in
--      the sheet: taken out, so the sheet's words show. Only those fields.
--
-- Run once on dev and once on live, BEFORE `npm run build`:
--   psql "$DATABASE_URL" -P pager=off -v ON_ERROR_STOP=1 -f db/016_content_action_plan_14_oct_2026.sql
-- Safe to run twice. og_title / og_description / twitter_title follow only
-- where they still equal the old value. The last queries list what was found.

BEGIN;

-- ------------------------------------------------------------- 1. posts --
CREATE TEMP TABLE new_seo (slug text PRIMARY KEY, meta_title text, h1 text, meta_description text) ON COMMIT DROP;

CREATE TEMP TABLE before ON COMMIT DROP AS
SELECT p.slug, p.meta_title, p.title, p.meta_description FROM posts p JOIN new_seo n ON n.slug = p.slug;

UPDATE posts p SET
  og_title         = CASE WHEN n.meta_title IS NOT NULL AND p.og_title = p.meta_title THEN n.meta_title ELSE p.og_title END,
  twitter_title    = CASE WHEN n.meta_title IS NOT NULL AND p.twitter_title = p.meta_title THEN n.meta_title ELSE p.twitter_title END,
  og_description   = CASE WHEN n.meta_description IS NOT NULL AND p.og_description = p.meta_description THEN n.meta_description ELSE p.og_description END,
  meta_title       = COALESCE(n.meta_title, p.meta_title),
  title            = COALESCE(n.h1, p.title),
  meta_description = COALESCE(n.meta_description, p.meta_description),
  updated_at       = now()
FROM new_seo n
WHERE p.slug = n.slug
  AND (p.meta_title IS DISTINCT FROM COALESCE(n.meta_title, p.meta_title)
    OR p.title IS DISTINCT FROM COALESCE(n.h1, p.title)
    OR p.meta_description IS DISTINCT FROM COALESCE(n.meta_description, p.meta_description));

-- ------------------------------------------- 2. Admin -> Pages overrides --
CREATE TEMP TABLE clear_fields (key text, path text) ON COMMIT DROP;

CREATE TEMP TABLE cleared_report ON COMMIT DROP AS
SELECT c.key, c.path, pc.published ->> c.path AS published_value, pc.draft ->> c.path AS draft_value
  FROM clear_fields c JOIN page_content pc ON pc.key = c.key
 WHERE pc.published ? c.path OR COALESCE(pc.draft ? c.path, false);

UPDATE page_content pc SET
  published = pc.published - ARRAY(SELECT path FROM clear_fields c WHERE c.key = pc.key),
  draft     = CASE WHEN pc.draft IS NULL THEN NULL ELSE pc.draft - ARRAY(SELECT path FROM clear_fields c WHERE c.key = pc.key) END
 WHERE pc.key IN (SELECT key FROM clear_fields);

-- The whole-list shape: META stored as one array. Blank the field so the code's shows.
CREATE TEMP TABLE clear_array (key text, i int, field text) ON COMMIT DROP;

UPDATE page_content pc SET published = jsonb_set(pc.published, ARRAY['META', a.i::text, a.field], '""'::jsonb)
  FROM clear_array a
 WHERE pc.key = a.key AND jsonb_typeof(pc.published -> 'META') = 'array'
   AND COALESCE(pc.published #>> ARRAY['META', a.i::text, a.field], '') <> '';
UPDATE page_content pc SET draft = jsonb_set(pc.draft, ARRAY['META', a.i::text, a.field], '""'::jsonb)
  FROM clear_array a
 WHERE pc.key = a.key AND pc.draft IS NOT NULL AND jsonb_typeof(pc.draft -> 'META') = 'array'
   AND COALESCE(pc.draft #>> ARRAY['META', a.i::text, a.field], '') <> '';

-- -------------------------------------------------------------- report --
SELECT count(*) AS posts_in_sheet, (SELECT count(*) FROM before) AS found_in_this_database FROM new_seo;

SELECT n.slug AS not_in_this_database
  FROM new_seo n LEFT JOIN posts p ON p.slug = n.slug
 WHERE p.id IS NULL ORDER BY n.slug;

SELECT key, path, published_value AS admin_edit_removed, draft_value AS draft_edit_removed FROM cleared_report ORDER BY key, path;

COMMIT;
